  sha256Text: ['Hash the supplied text with Node crypto default UTF-8 and return sha256: plus 64 lowercase hex digits. Does not canonicalize JSON or version the identity. Byte size elsewhere must use UTF-8, not JavaScript string length.', "sha256Text('A');"],
